insert into public.facts (id, categoria, frase, risposte, spiegazione, stato) values
('SCI-001','Science','Ogni secondo il Sole trasforma ____ in energia.',array['circa 4 milioni di tonnellate di materia'],'È la massa che la fusione nucleare trasforma in energia ogni secondo. Il Sole è così grande che può andare avanti così per miliardi di anni.','Verificato'),
('SCI-002','Science','La Luna si allontana dalla Terra di circa ____.',array['3,8 cm all''anno'],'Lo misuriamo con i laser puntati sui riflettori lasciati dalle missioni Apollo. La causa sono le maree.','Verificato'),
('SCI-005','Science','L''elio fu scoperto prima ____ che sulla Terra.',array['nel Sole'],'Fu visto nella luce solare nel 1868; sulla Terra fu trovato solo 27 anni dopo. Il nome viene da Helios, il Sole in greco.','Verificato'),
('SCI-006','Science','In tutta la crosta terrestre ci sono al massimo ____ di francio.',array['circa 30 grammi'],'Il francio è radioattivo e decade in pochi minuti: si forma e sparisce di continuo.','Verificato'),
('SCI-007','Science','Nel 1669 un alchimista scoprì il fosforo ____.',array['facendo evaporare dell''urina'],'Hennig Brand cercava di ottenere l''oro. Trovò invece una sostanza che brillava al buio.','Verificato'),
('SCI-008','Science','____ nacque come farmaco contro i dolori al cuore.',array['Il Viagra'],'Il farmaco era in sperimentazione per il cuore: i volontari segnalarono un effetto collaterale inatteso e l''azienda cambiò strada.','Verificato'),
('SCI-009','Science','Il nucleo della Terra è caldo più o meno quanto ____.',array['la superficie del Sole'],'Tra 5.000 e 6.000 °C.','Verificato'),
('SCI-010','Science','Il ____ dall''uomo arriva a circa 12 km.',array['buco più profondo mai scavato'],'12.262 metri, per la precisione. Non ha nemmeno raggiunto il mantello terrestre.','Verificato'),
('SCI-011','Science','In un ____ passano circa 80 milioni di batteri.',array['bacio di dieci secondi'],'Lo ha misurato uno studio facendo baciare delle coppie e analizzando la saliva prima e dopo.','Verificato'),
('SCI-012','Science','I vasi sanguigni di una persona, messi in fila, sarebbero lunghi ____.',array['migliaia di chilometri'],'La cifra famosa è 100.000 km, ma le stime recenti parlano di 9.000-19.000 km di capillari.','Verificato'),
('SCI-013','Science','Il cervello non sente dolore, quindi ____.',array['si può operare da svegli'],'Non ha recettori del dolore. In certi interventi il paziente resta sveglio e parla, per aiutare i chirurghi a evitare le zone importanti.','Verificato, da ricontrollare'),
('SCI-014','Science','C''è un batterio che resiste a radiazioni estreme ed è soprannominato "____".',array['Conan il Batterio'],'Si chiama Deinococcus radiodurans e sopporta dosi di radiazioni che ucciderebbero qualsiasi altro essere vivente.','Verificato, da ricontrollare'),
('SCI-015','Science','Per dimostrare che le ulcere vengono da un batterio, un medico ____.',array['bevve un liquido pieno di batteri'],'Barry Marshall bevve l''Helicobacter e si ammalò, come previsto. Vinse il Nobel nel 2005.','Verificato, da ricontrollare'),
('SCI-016','Science','Nel 1929 un medico ____, e poi vinse il Nobel.',array['si infilò un tubicino fino al cuore'],'Werner Forssmann voleva dimostrare che si poteva fare senza morire. Oggi il cateterismo cardiaco è routine.','Verificato, da ricontrollare'),
('SCI-017','Science','Dopo aver preso apposta la prima dose di LSD, il suo scopritore ____.',array['tornò a casa in bici'],'Albert Hofmann l''aveva scoperto per caso tre giorni prima. Quel viaggio in bici è rimasto famoso.','Verificato, da ricontrollare'),
('SCI-018','Science','____ contengono una sostanza che rilascia cianuro.',array['I semi di mela'],'Si chiama amigdalina. Ne servirebbero moltissimi, ben masticati, per essere pericolosi.','Verificato, da ricontrollare'),
('SCI-019','Science','Per molte piante ____ è un pesticida naturale contro gli insetti.',array['la caffeina'],'La pianta la produce per difendersi dagli insetti che la mangiano.','Verificato, da ricontrollare'),
('SCI-020','Science','Il bambù può crescere fino a ____ in un solo giorno.',array['circa 90 cm'],'Il record registrato è di circa 91 cm in 24 ore.','Verificato, da ricontrollare'),
('SCI-021','Science','Il DNA di una sola cellula umana, srotolato, è lungo ____.',array['circa 2 metri'],'Sta arrotolato in un nucleo molto più piccolo di un granello di polvere.','Verificato, da ricontrollare'),
('SCI-022','Science','Prima del primo test atomico Enrico Fermi accettava scommesse sul fatto che l''esplosione ____.',array['incendiasse l''atmosfera'],'Test Trinity, 1945. Era umorismo nero: i calcoli avevano già escluso il rischio.','Verificato, da ricontrollare'),
('SCI-023','Science','Ogni secondo il tuo corpo è attraversato da ____.',array['circa 100.000 miliardi di neutrini'],'Arrivano dal Sole (è una stima). Non interagiscono quasi con nulla e attraversano anche tutta la Terra.','Stima o ipotesi'),
('SCI-024','Science','Due orologi atomici messi a ____ segnano un tempo diverso.',array['33 cm di differenza d''altezza'],'Esperimento del NIST, 2010: più in alto il tempo scorre un filo più veloce, come previsto dalla relatività.','Verificato, da ricontrollare'),
('SCI-025','Science','Senza le correzioni della relatività il GPS sbaglierebbe di ____.',array['circa 10 km al giorno'],'Sui satelliti il tempo scorre in modo leggermente diverso che a terra, e gli orologi vanno corretti.','Verificato, da ricontrollare'),
('SCI-026','Science','Il petrolio non viene dai dinosauri ma da ____.',array['antico plancton e alghe marine'],'Organismi microscopici sepolti sui fondali e trasformati da calore e pressione in milioni di anni.','Verificato, da ricontrollare'),
('SCI-027','Science','Parte dell''oro dell''universo si sarebbe formata ____.',array['nelle collisioni tra stelle di neutroni'],'Quanto oro venga davvero da lì è ancora discusso.','Stima o ipotesi'),
('SCI-028','Science','L''ossigeno liquido è azzurro e ____.',array['viene attratto da un magnete'],'Tra i poli di una calamita potente l''ossigeno liquido resta sospeso.','Verificato, da ricontrollare'),
('SCI-029','Science','Il gallio è un metallo che ____.',array['si scioglie in mano'],'Fonde a circa 30 °C, meno della temperatura del corpo.','Verificato, da ricontrollare'),
('SCI-030','Science','Sulla Terra cadono ____ al secondo.',array['circa 40-50 fulmini'],'Sono milioni di fulmini ogni giorno.','Verificato, da ricontrollare'),
('SCI-031','Science','L''arcobaleno è in realtà ____.',array['un cerchio completo'],'Da terra se ne vede solo metà, perché l''orizzonte nasconde il resto. Da un aereo a volte si vede tutto.','Verificato, da ricontrollare'),
('SCI-032','Science','Quando un fulmine colpisce la sabbia la fonde in ____.',array['tubi di vetro'],'Si chiamano fulguriti.','Verificato, da ricontrollare'),
('SCI-034','Science','Attorno a un quasar lontanissimo c''è una gigantesca nube di vapore acqueo, che contiene ____ l''acqua degli oceani terrestri.',array['140.000 miliardi di volte'],'È il quasar APM 08279+5255, a circa 12 miliardi di anni luce: è la più grande massa d''acqua mai trovata.','Verificato'),
('SCI-035','Science','Sul pianeta HD 189733b si ritiene che ____.',array['piova vetro'],'Il pianeta è HD 189733b: il vetro sarebbe spinto di lato da venti di migliaia di km/h.','Stima o ipotesi'),
('SCI-036','Science','Su Titano, la luna di Saturno, ____ e ci sono laghi di idrocarburi.',array['piove metano'],'Su Titano ci sono anche laghi di idrocarburi.','Verificato, da ricontrollare'),
('SCI-037','Science','Su Mercurio, il pianeta più vicino al Sole, c''è ____.',array['ghiaccio d''acqua'],'Si trova nei crateri dei poli, che restano sempre all''ombra.','Verificato, da ricontrollare'),
('SCI-038','Science','Su Marte i tramonti hanno ____.',array['un alone azzurro'],'Il contrario della Terra: il resto del cielo resta rossastro.','Verificato, da ricontrollare'),
('SCI-039','Science','Il vulcano Olympus Mons, su Marte, è alto ____.',array['circa 22 km'],'Circa due volte e mezza l''Everest.','Verificato, da ricontrollare'),
('SCI-040','Science','Sulla Stazione Spaziale gli astronauti vedono ____ al giorno.',array['circa 16 albe e 16 tramonti'],'La stazione fa un giro completo della Terra in circa un''ora e mezza.','Verificato, da ricontrollare'),
('SCI-041','Science','Sulla Stazione Spaziale ____ vengono riciclati in acqua da bere.',array['urina e sudore'],'Portare acqua nello spazio costa moltissimo, quindi a bordo si ricicla quasi tutto.','Verificato, da ricontrollare'),
('SCI-042','Science','Gli astronauti dell''Apollo dicevano che ____ odorava di ____.',array['la polvere lunare','polvere da sparo'],'La sentivano sulle tute una volta rientrati nel modulo lunare.','Verificato, da ricontrollare'),
('SCI-044','Science','La Grande Macchia Rossa di Giove è una tempesta che viene osservata da ____.',array['circa 190 anni'],'È osservata in modo continuo dall''Ottocento, ed è grande più o meno quanto la Terra.','Verificato, da ricontrollare'),
('SCI-045','Science','Una pulsar ruota su sé stessa ____.',array['716 volte al secondo'],'Si chiama PSR J1748-2446ad ed è una stella morta, piccola e densissima.','Verificato'),
('SCI-046','Science','I lampi di raggi gamma furono scoperti da ____ costruiti per ____.',array['satelliti','spiare i test nucleari'],'Nel 1967 cercavano esplosioni atomiche sulla Terra e videro invece lampi provenienti dallo spazio.','Verificato'),
('SCI-047','Science','Il sudore fresco è quasi inodore: la puzza la fanno ____.',array['i batteri della pelle'],'Il sudore è quasi solo acqua e sali: l''odore nasce quando i batteri lo decompongono.','Verificato'),
('SCI-048','Science','Il ____ contiene tracce di caffeina.',array['caffè decaffeinato'],'Il processo di decaffeinizzazione non la toglie tutta.','Verificato'),
('SCI-049','Science','Per spiegare il nanosecondo, l''informatica Grace Hopper mostrava ____.',array['un filo di 30 cm'],'È la distanza che la luce percorre in un nanosecondo.','Verificato'),
('SCI-050','Science','Nella stanza più silenziosa del mondo si può sentire ____ quando si aprono e chiudono.',array['il rumore delle palpebre'],'È una camera della Microsoft che misura circa -20,6 decibel: meno del silenzio.','Verificato'),
('FOO-001','Food & Drink','Frank Epperson a 11 anni, dimenticò fuori di notte acqua e soda con un bastoncino: nacque il ____.',array['Popsicle'],'Era il 1905. Anni dopo brevettò l''idea.','Verificato'),
('FOO-002','Food & Drink','Thomas Adams voleva trasformare una resina messicana in gomma, non ci riuscì e ne fece ____.',array['il chewing gum'],'Il chicle era la resina che in Messico si masticava da secoli.','Verificato'),
('FOO-003','Food & Drink','Gli antichi Romani amavano così tanto un''erba, il silfio, che ____.',array['la fecero estinguere'],'Il silfio si usava in cucina e come medicina. Non si riuscì mai a coltivarlo.','Verificato'),
('FOO-004','Food & Drink','Nel 1957 la BBC mandò in onda un pesce d''aprile e mostrò degli svizzeri che raccoglievano ____: molti chiesero come coltivarli.',array['spaghetti dagli alberi'],'All''epoca in Gran Bretagna la pasta era poco conosciuta, e molti ci cascarono.','Verificato'),
('FOO-005','Food & Drink','Prima dell''apriscatole le scatolette si aprivano con ____, come consigliavano i produttori.',array['martello e scalpello'],'L''apriscatole fu brevettato quasi cinquant''anni dopo le scatolette.','Verificato'),
('FOO-007','Food & Drink','Dom Pérignon, il monaco dello champagne, considerava ____ un difetto.',array['le bollicine'],'Cercava di eliminarle dal vino: all''epoca facevano esplodere le bottiglie.','Verificato'),
('FOO-008','Food & Drink','Il gusto umami fu scoperto nel 1908 da un chimico giapponese che ____.',array['studiava un''alga'],'Kikunae Ikeda studiava l''alga kombu, usata per il brodo, e ne isolò la sostanza responsabile del sapore.','Verificato'),
('FOO-011','Food & Drink','La bacca del miracolo per circa un''ora fa sembrare ____, grazie alla miracolina.',array['dolci i cibi acidi'],'Una proteina della bacca, la miracolina, inganna per un po'' i recettori del dolce sulla lingua.','Verificato'),
('FOO-012','Food & Drink','I pistacchi umidi trasportati in grandi quantità possono ____.',array['prendere fuoco da soli'],'Contengono moltissimo olio: se sono umidi e ammassati si scaldano da soli. Succede solo con i grandi carichi.','Verificato'),
('FOO-014','Food & Drink','L''acqua tonica, sotto luce ultravioletta, ____.',array['emette luce azzurra'],'Merito del chinino, che assorbe i raggi ultravioletti e li riemette come luce visibile.','Verificato'),
('FOO-015','Food & Drink','Il salmone è rosa perché mangia gamberetti, che ____.',array['contengono una sostanza rossa'],'Il pigmento si chiama astaxantina. Al salmone d''allevamento viene aggiunto nel mangime.','Verificato'),
('FOO-016','Food & Drink','Nel 1893 la Corte Suprema USA stabilì che il pomodoro è un ortaggio, per ____.',array['questioni di tasse'],'Sulla verdura importata si pagava un dazio, sulla frutta no. Per la botanica il pomodoro resta un frutto.','Verificato'),
('FOO-017','Food & Drink','Un’ape operaia, in tutta la sua vita, produce circa ____.',array['un dodicesimo di cucchiaino di miele'],'Per un solo barattolo serve il lavoro di migliaia di api.','Verificato'),
('FOO-018','Food & Drink','Per fare un litro di sciroppo d''acero servono ____.',array['circa 40 litri di linfa'],'La linfa è quasi tutta acqua e va fatta bollire a lungo.','Verificato'),
('FOO-019','Food & Drink','Nel Settecento Federico il Grande assunse 400 "annusatori" per scovare chi ____.',array['tostava caffè senza permesso'],'Voleva che i prussiani bevessero birra invece di caffè importato. Molti annusatori erano ex soldati.','Verificato'),
('FOO-020','Food & Drink','Nel 2020 la Corte suprema irlandese stabilì che il pane di Subway ____.',array['non è pane'],'Conteneva troppo zucchero: circa il 10% contro il limite del 2%.','Verificato'),
('FOO-021','Food & Drink','Negli USA l''haggis tradizionale scozzese è vietato perché contiene ____.',array['polmone di pecora'],'Dal 1971 il polmone non si può vendere come cibo per le persone.','Verificato'),
('FOO-022','Food & Drink','Negli USA le uova Kinder Sorpresa sono illegali perché una legge vieta i dolci con ____.',array['una sorpresa che non si mangia'],'La legge è del 1938. Il Kinder Joy è permesso perché il giocattolo è separato dal dolce.','Verificato'),
('FOO-023','Food & Drink','In Islanda ____ fu vietata fino al 1989.',array['la birra forte'],'Vino e liquori, invece, erano tornati legali decenni prima.','Verificato'),
('FOO-024','Food & Drink','In Giappone ____ fu vietato per circa 1.200 anni.',array['mangiare carne'],'Dal 675 al 1872, quando l''imperatore mangiò manzo in pubblico. All''inizio il divieto riguardava solo alcune carni e alcuni mesi.','Verificato'),
('FOO-025','Food & Drink','Nel Settecento in Francia il Parlamento vietò ____.',array['le patate'],'Dal 1748 al 1772: si pensava che diffondessero malattie, come la lebbra.','Verificato'),
('FOO-027','Food & Drink','Un''antica legge romana vietava di servire ai banchetti qualunque uccello tranne ____.',array['una gallina non ingrassata'],'Era la Lex Fannia, del 161 a.C., contro il lusso a tavola.','Verificato'),
('FOO-028','Food & Drink','Nel 2011 l''Ungheria introdusse una "____".',array['tassa sulle patatine'],'Colpisce i cibi con troppo sale, zucchero o caffeina. I soldi vanno alla sanità.','Verificato'),
('FOO-031','Food & Drink','____ fu scoperta tenendo una ciotola d''acqua sopra una vasca di birra in fermentazione.',array['L''acqua gassata'],'Lo fece Joseph Priestley nel 1767: l''acqua assorbì l''anidride carbonica prodotta dalla birra.','Verificato'),
('FOO-032','Food & Drink','Durante il Proibizionismo il governo USA ____.',array['avvelenò l''alcol industriale'],'Aggiunse metanolo e altre sostanze per scoraggiare chi lo trasformava in liquori. Si stimano circa 10.000 morti.','Verificato'),
('FOO-034','Food & Drink','La Svizzera vietò l''assenzio dopo che un viticoltore che ne aveva bevuto ____.',array['uccise la famiglia'],'Il delitto è del 1905, il divieto del 1910. L''uomo aveva bevuto anche molto altro.','Verificato'),
('FOO-035','Food & Drink','Dopo la presidenza George Washington gestì ____ degli USA.',array['la più grande distilleria di whiskey'],'Nel 1799 produsse circa 40.000 litri.','Verificato'),
('FOO-036','Food & Drink','In origine ____ conteneva citrato di litio.',array['la 7 Up'],'Il litio è un farmaco per l''umore. Nel 1929 la bibita si chiamava "Bib-Label Lithiated Lemon-Lime Soda".','Verificato'),
('FOO-038','Food & Drink','La più antica bottiglia di vino ancora liquido fu sigillata da ____.',array['uno strato di olio d''oliva'],'Ha circa 1.700 anni. L''olio ha tenuto lontana l''aria.','Verificato'),
('FOO-040','Food & Drink','Dopo la "Beer Flood" di Londra, che fece otto morti, la birreria ottenne ____.',array['un rimborso delle tasse sulla birra persa'],'Era il 1814. L''inchiesta dichiarò che era stato un incidente.','Verificato'),
('FOO-041','Food & Drink','In una delle prime colonie inglesi d''America gli archeologi hanno trovato ____ mangiata dai coloni.',array['le ossa di una ragazza'],'Jamestown, inverno 1609-1610: lo chiamano "il tempo della fame". La ragazza aveva 14 anni.','Verificato'),
('FOO-042','Food & Drink','Nel 1858 in Inghilterra una ventina di persone ____ perché in dei dolcetti finì ____.',array['morirono','dell''arsenico'],'A Bradford un apprendista lo prese al posto della polvere di gesso, usata per risparmiare sullo zucchero.','Verificato'),
('FOO-043','Food & Drink','Nel 1902 un chimico americano reclutò 12 volontari per ____.',array['mangiare cibo con conservanti tossici'],'Harvey Wiley voleva dimostrare che facevano male. Il gruppo fu chiamato "Poison Squad".','Verificato'),
('FOO-045','Food & Drink','Durante il Proibizionismo migliaia di americani rimasero paralizzati bevendo ____.',array['estratto di zenzero'],'Era un "medicinale" alcolico, adulterato con una sostanza tossica per i nervi.','Verificato'),
('FOO-048','Food & Drink','In Canada dei ladri rubarono tonnellate di sciroppo d''acero e ____.',array['riempivano d''acqua i barili vuotati'],'Québec, 2012: il furto andò avanti per quasi un anno prima che qualcuno se ne accorgesse.','Verificato'),
('FOO-050','Food & Drink','Nel 1960 in Inghilterra oltre 100.000 ____ morirono per un ____.',array['tacchini','mangime ammuffito'],'Così fu scoperta l''aflatossina, una tossina prodotta da una muffa.','Verificato'),
('HIS-001','History','Nel 1518 a Strasburgo centinaia di persone, per giorni, ____.',array['ballarono senza riuscire a fermarsi'],'Secondo cronache scritte più tardi, alcuni morirono di sfinimento, ma il numero è incerto. Ancora oggi non si sa cosa causò questa «epidemia di ballo».','Verificato'),
('HIS-003','History','In Europa, per secoli, le farmacie vendevano come medicina ____.',array['mummie egizie macinate'],'Si pensava che la polvere di mummia curasse un po'' di tutto.','Non verificato (da memoria)'),
('DRK-001','Dark/Politically incorrect','Nel 1919 a Boston, in una giornata qualunque, 21 persone morirono travolte da ____.',array['un''onda di melassa'],'Il 15 gennaio 1919 un enorme serbatoio cedette e l''onda travolse un quartiere di Boston. Molti morirono soffocati dallo sciroppo; i feriti furono circa 150.','Verificato'),
('HIS-004','History','L''inventore della benzina al piombo morì ____.',array['strangolato dalle corde che aveva inventato per alzarsi dal letto'],'Si chiamava Thomas Midgley e inventò anche i freon che bucarono l''ozono. Paralizzato dalla poliomielite, si era costruito un sistema di corde e carrucole. Morì nel 1944.','Verificato'),
('HIS-005','History','Il re inglese Giorgio II morì ____.',array['sul water'],'Era il 1760. Fu trovato a terra appena dopo essere stato sulla seggetta, il «water» dell''epoca. L''autopsia trovò una lacerazione dell''aorta, forse per lo sforzo.','Verificato'),
('HIS-006','History','Nel 1932 l''esercito australiano andò a combattere con le mitragliatrici contro ____, e perse.',array['gli emù'],'Circa 20.000 emù devastavano i campi di grano. I soldati spararono migliaia di colpi uccidendone pochi, e furono ritirati due volte nel giro di poche settimane.','Verificato'),
('HIS-007','History','Nella Seconda guerra mondiale gli USA progettarono di lanciare sul Giappone ____ con ____.',array['pipistrelli','bombe incendiarie addosso'],'L''idea era che i pipistrelli andassero a nascondersi sotto i tetti delle case di legno, dove gli ordigni avrebbero appiccato il fuoco. Il progetto, chiamato X-Ray, non fu mai usato.','Verificato'),
('FOO-051','Food & Drink','Il dottor Kellogg, quello dei cereali, sosteneva che il cibo insipido scoraggiasse ____.',array['la masturbazione'],'I cornflakes però nacquero come cibo digeribile per i pazienti della sua clinica, non per questo scopo.','Verificato'),
('HIS-008','History','Negli anni ''30 una pubblicità consigliava alle donne di usare ____ per l''igiene intima.',array['un disinfettante per la casa'],'Era il Lysol. «Igiene intima» era un modo velato per dire contraccezione, allora illegale. Non funzionava e a molte donne causò ustioni.','Verificato'),
('HIS-009','History','Nell''Ottocento, per calmare i neonati che mettevano i denti, si usava ____.',array['uno sciroppo con morfina'],'Il più famoso era lo sciroppo della signora Winslow, nato negli Stati Uniti nel 1849: un cucchiaino conteneva abbastanza morfina da uccidere un bambino. Lo chiamavano «l''ammazzabambini».','Verificato'),
('HIS-010','History','Alla maratona olimpica del 1904 il vincitore corse aiutato da ____.',array['veleno per topi e brandy'],'Si chiamava Thomas Hicks: gli diedero stricnina, un veleno per topi che a piccole dosi si usava come stimolante, con albume d''uovo e brandy. Arrivò al traguardo quasi portato a braccia.','Verificato'),
('DRK-002','Dark/Politically incorrect','Nel 1906 lo zoo del Bronx espose ____ nella gabbia delle scimmie.',array['un uomo congolese'],'Si chiamava Ota Benga, del popolo Mbuti. Fu esposto per alcuni giorni, finché le proteste dei pastori delle chiese nere costrinsero lo zoo a smettere. Lo zoo si è scusato nel 2020.','Verificato'),
('DRK-004','Dark/Politically incorrect','Nell''897 papa Formoso, già morto da tempo, fu riesumato e ____.',array['processato'],'È il «sinodo del cadavere»: papa Stefano VI fece vestire il corpo da papa, lo mise sul trono e lo condannò. Poi lo fece gettare nel Tevere.','Verificato'),
('HIS-011','History','Per screditare la corrente alternata, un collaboratore di Edison ____.',array['fulminava animali in pubblico'],'Si chiamava Harold Brown e usava il laboratorio di Edison: nel 1888 uccise con la corrente alternata cani, vitelli e un cavallo. Era la «guerra delle correnti».','Verificato'),
('HIS-012','History','Un dittatore del Turkmenistan cambiò i nomi dei mesi, e ad aprile diede ____.',array['il nome di sua madre'],'Era Saparmurat Niyazov, nel 2002. Gennaio prese il suo soprannome, Turkmenbashi. Il suo successore rimise i nomi normali nel 2008.','Verificato'),
('DRK-005','Dark/Politically incorrect','Nell’Ottocento in Scozia si coprivano le tombe con ____ per non far rubare i cadaveri.',array['gabbie di ferro'],'Si chiamavano mortsafe. I cadaveri freschi si vendevano alle scuole di medicina per le lezioni di anatomia. Il problema finì quasi del tutto nel 1832, quando una legge permise di usare i corpi non reclamati.','Verificato'),
('HIS-013','History','Durante l''assedio di Leningrado alcuni scienziati morirono di fame pur di non mangiare ____.',array['i semi che custodivano'],'Era la banca dei semi fondata da Nikolai Vavilov, una delle più grandi del mondo. Alcuni morirono alla scrivania, con tonnellate di semi a pochi passi.','Verificato'),
('HIS-014','History','Nel 1939 ____ fu candidato al Nobel per la Pace.',array['Hitler'],'Lo propose un deputato svedese antinazista, per ironia: protestava contro l''accordo di Monaco. Le reazioni furono così dure che ritirò la candidatura dopo pochi giorni.','Verificato'),
('SCI-051','Science','Dopo la morte di Einstein il medico dell''autopsia gli rubò ____ e lo tenne in ____ per decenni.',array['il cervello','dei barattoli'],'Il medico che fece l''autopsia nel 1955 lo prelevò senza permesso e lo tenne con sé per anni.','Non verificato (da memoria)'),
('DRK-006','Dark/Politically incorrect','Nel 1851 un medico americano inventò la «drapetomania», una malattia mentale con cui spiegava ____.',array['la fuga degli schiavi'],'La inventò il medico Samuel Cartwright nel 1851, unendo le parole greche per «fuggitivo» e «follia». Per lui uno schiavo che voleva scappare non poteva che essere malato.','Verificato'),
('DRK-007','Dark/Politically incorrect','Nel 1949 il Nobel per la Medicina premiò chi aveva inventato ____.',array['un''operazione che tagliava il cervello'],'Era il portoghese Egas Moniz, premiato per la «leucotomia», poi chiamata lobotomia. Fu praticata su decine di migliaia di pazienti prima di essere abbandonata.','Verificato'),
('HIS-017','History','Pietro il Grande tassava chi portava ____.',array['la barba'],'Era il 1698: voleva che i russi sembrassero più europei. Chi pagava riceveva un gettone, d''argento per i nobili e di rame per gli altri, da mostrare.','Verificato'),
('ANI-002','Animal kingdom','Il vombato è l''unico animale che fa la cacca ____.',array['a forma di cubo'],'Usa i cubetti per segnare il territorio: non rotolano via.','Non verificato (da memoria)'),
('GEO-001','Geography','L''animale nazionale della Scozia è ____.',array['l''unicorno'],'Compare sullo stemma reale scozzese da secoli.','Non verificato (da memoria)'),
('POP-001','Pop culture','Il primo oggetto venduto su eBay fu un ____.',array['puntatore laser rotto'],'Il compratore spiegò che collezionava puntatori laser rotti.','Verificato'),
('ANI-003','Animal kingdom','In Svizzera è illegale tenere ____ senza ____.',array['un porcellino d''India','un compagno'],'Sono animali sociali, e la legge svizzera considera la solitudine un maltrattamento.','Non verificato (da memoria)'),
('GEO-002','Geography','In Giappone puoi pagare per affittare ____ o ____.',array['un finto parente','un finto amico'],'Ci sono agenzie che forniscono attori per matrimoni, cene e funerali.','Non verificato (da memoria)'),
('ANI-004','Animal kingdom','I gamberetti hanno ____.',array['il cuore nella testa'],'Si trova nella parte anteriore del corpo, sotto la corazza.','Non verificato (da memoria)'),
('ANI-005','Animal kingdom','Nel 1945 un pollo di nome Mike visse ____.',array['18 mesi senza testa'],'Il colpo d''ascia aveva lasciato intatta la parte del cervello che regola le funzioni vitali. Il padrone lo nutriva con un contagocce.','Non verificato (da memoria)'),
('HIS-018','History','Gli astronauti dell''Apollo 11, senza assicurazione sulla vita, ____ da far vendere alle famiglie in caso di morte.',array['firmarono autografi'],'Nessuno li assicurava per una missione così rischiosa.','Non verificato (da memoria)'),
('POP-002','Pop culture','Il compositore Lully morì dopo essersi colpito ____.',array['un piede con il bastone da direttore'],'All''epoca si dirigeva battendo a terra un lungo bastone. La ferita andò in cancrena. Lui rifiutò l''amputazione e la cancrena lo uccise.','Verificato'),
('GEO-003','Geography','D''estate la Torre Eiffel ____.',array['si allunga di una decina di centimetri'],'Con il caldo il ferro si dilata.','Non verificato (da memoria)'),
('ANI-006','Animal kingdom','Un pinguino dello zoo di Edimburgo è ____.',array['un generale dell''esercito norvegese'],'Si chiama Sir Nils Olav ed è la mascotte della Guardia reale norvegese.','Non verificato (da memoria)'),
('GEO-004','Geography','Un''isola al confine tra Francia e Spagna ____.',array['cambia nazionalità ogni sei mesi'],'È l''Isola dei Fagiani, su un fiume: i due paesi la amministrano a turno.','Non verificato (da memoria)'),
('ANI-007','Animal kingdom','La CIA provò a spiare i sovietici con ____.',array['un gatto con un microfono impiantato'],'Il progetto si chiamava Acoustic Kitty e fu un fallimento costosissimo.','Non verificato (da memoria)'),
('HIS-019','History','Nel 1958 gli USA studiarono un piano per ____.',array['far esplodere una bomba atomica sulla Luna'],'Doveva essere una dimostrazione di forza verso l''URSS. Il piano fu abbandonato.','Non verificato (da memoria)'),
('GEO-005','Geography','In Islanda esiste un''app per ____.',array['evitare di uscire con un proprio cugino'],'Gli islandesi sono pochi e molti sono imparentati: l''app controlla un archivio genealogico nazionale.','Non verificato (da memoria)'),
('FOO-055','Food & Drink','L''inventore del tubo delle Pringles volle essere sepolto in parte ____.',array['dentro un tubo di Pringles'],'Fredric Baur morì nel 2008. I figli comprarono il tubo al supermercato andando al funerale.','Verificato'),
('HIS-020','History','La parola "robot" viene dal ceco, dove significa ____.',array['lavoro forzato'],'La parola comparve nel 1920 in un''opera teatrale dello scrittore ceco Karel Čapek.','Non verificato (da memoria)'),
('HIS-021','History','Gli antichi Romani lavavano i vestiti ____.',array['con l''urina'],'L''ammoniaca contenuta nell''urina funziona da detergente.','Non verificato (da memoria)'),
('GEO-006','Geography','La bandiera del Nepal è l''unica al mondo ____.',array['non rettangolare'],'È formata da due triangoli sovrapposti.','Non verificato (da memoria)'),
('DRK-008','Dark/Politically incorrect','Fino al 1981 in Italia chi uccideva la moglie, la figlia o la sorella sorprese con un amante rischiava ____.',array['solo fino a 7 anni di carcere'],'Era il «delitto d''onore» dell''articolo 587 del codice penale: da 3 a 7 anni di carcere, molto meno di un omicidio normale. Valeva anche per una donna che uccideva il marito. Fu abrogato nel 1981.','Verificato'),
('DRK-009','Dark/Politically incorrect','Fino al ____ in Italia, per evitare la condanna per stupro, bastava ____.',array['1981','sposare la vittima'],'Era il «matrimonio riparatore» dell''articolo 544 del codice penale. Nel 1966 Franca Viola fu la prima a rifiutarlo pubblicamente e fece condannare il suo rapitore.','Verificato'),
('HIS-022','History','Nel 1977, l''anno in cui è uscito Star Wars, in Francia ci fu ____.',array['l''ultima esecuzione con la ghigliottina'],'Il condannato era Hamida Djandoubi, ghigliottinato a Marsiglia il 10 settembre 1977: il giorno dopo Star Wars veniva presentato in Francia. La pena di morte fu abolita nel 1981.','Verificato'),
('HIS-023','History','Secondo la legge romana, chi uccideva il padre doveva essere gettato in acqua in un sacco con ____.',array['un cane, un gallo, una vipera e una scimmia'],'Era la «pena del sacco». Non è sicuro che sia mai stata eseguita con tutti e quattro gli animali: il cane e il gallo compaiono nelle fonti solo nel III secolo.','Verificato'),
('DRK-012','Dark/Politically incorrect','Nel 1916 un''elefantessa da circo di nome Mary fu ____ davanti alla folla.',array['impiccata a una gru'],'Aveva ucciso un addetto del circo, e il pubblico pretese l''esecuzione.','Non verificato (da memoria)'),
('DRK-014','Dark/Politically incorrect','Ted Bundy, durante il processo, ____.',array['si sposò in aula'],'Sfruttò una vecchia legge della Florida: bastava dichiararsi sposati davanti a un giudice.','Non verificato (da memoria)'),
('DRK-016','Dark/Politically incorrect','Issei Sagawa uccise e mangiò una ragazza, poi fu liberato e diventò una celebrità e ____ per una rivista giapponese.',array['recensiva ristoranti'],'Successe a Parigi nel 1981. Fu dichiarato incapace di intendere, rimandato in Giappone e lì rimesso in libertà.','Non verificato (da memoria)'),
('DRK-017','Dark/Politically incorrect','In Germania un ____ trovò la sua vittima con un annuncio su internet, e un uomo si offrì volontario.',array['cannibale'],'Si chiamava Armin Meiwes, e successe nel 2001. La vittima, un ingegnere di Berlino, rispose al suo annuncio. Al secondo processo Meiwes fu condannato all''ergastolo per omicidio.','Verificato'),
('DRK-019','Dark/Politically incorrect','Nel Congo di Leopoldo II, a chi raccoglieva poca gomma ____.',array['tagliavano le mani'],'Il Congo era proprietà personale del re del Belgio. Morirono milioni di persone.','Non verificato (da memoria)'),
('DRK-020','Dark/Politically incorrect','All''Expo di Bruxelles del 1958 i visitatori potevano guardare uno "zoo umano" con ____.',array['un villaggio congolese'],'Il Congo era ancora una colonia belga. I visitatori si comportavano in modo così razzista che molti congolesi se ne andarono, e il villaggio chiuse prima della fine dell''Expo.','Verificato'),
('DRK-022','Dark/Politically incorrect','Per 40 anni il governo USA lasciò senza cure ____ con la sifilide per studiarla.',array['uomini neri'],'È lo studio di Tuskegee, in Alabama, durato dal 1932 al 1972. Ai malati non fu data la penicillina nemmeno quando era diventata la cura normale.','Verificato'),
('DRK-023','Dark/Politically incorrect','Nel primo Novecento negli USA le foto dei linciaggi venivano ____.',array['vendute come cartoline'],'La gente le spediva a parenti e amici come ricordo.','Non verificato (da memoria)'),
('DRK-024','Dark/Politically incorrect','Fino al ____ negli USA il linciaggio non era un reato federale.',array['2022'],'La legge porta il nome di Emmett Till, un ragazzo nero di 14 anni linciato nel 1955.','Non verificato (da memoria)'),
('DRK-026','Dark/Politically incorrect','Il Mississippi ha impiegato fino al ____ per approvare ufficialmente ____.',array['2013','l''abolizione della schiavitù'],'Il voto era arrivato nel 1995, ma i documenti non erano mai stati registrati.','Non verificato (da memoria)'),
('DRK-027','Dark/Politically incorrect','Nel 2000 in Alabama il 40% degli elettori votò per tenere nella costituzione ____.',array['il divieto di sposarsi tra bianchi e neri'],'Il divieto non era più applicabile dal 1967, ma era rimasto scritto. Fu cancellato con quel referendum, approvato con il 60% dei voti.','Verificato'),
('DRK-028','Dark/Politically incorrect','Il padre della ginecologia moderna faceva i suoi esperimenti ____.',array['su schiave senza anestesia'],'Si chiamava James Marion Sims, nell''Ottocento negli USA.','Non verificato (da memoria)'),
('DRK-029','Dark/Politically incorrect','Le cellule di una donna americana furono ____ e ____ senza il suo consenso.',array['prelevate','vendute in tutto il mondo'],'Henrietta Lacks morì nel 1951. Le sue cellule, le "HeLa", si usano ancora oggi nei laboratori. A differenza di altri campioni umani, le sue cellule dimostrarono una capacità straordinaria di sopravvivere e moltiplicarsi fuori dal corpo.','Non verificato (da memoria)'),
('DRK-031','Dark/Politically incorrect','A Dachau i medici nazisti ____ i prigionieri per studiare ____.',array['immergevano in acqua gelata','gli effetti del freddo estremo'],'Volevano capire come salvare i piloti tedeschi caduti in mare.','Non verificato (da memoria)'),
('DRK-032','Dark/Politically incorrect','Josef Mengele, il medico di Auschwitz, non fu mai processato: morì ____.',array['annegato su una spiaggia in Brasile'],'Visse nascosto in Sudamerica per oltre trent''anni.','Non verificato (da memoria)'),
('DRK-033','Dark/Politically incorrect','Nel 1927 la Corte Suprema USA approvò la sterilizzazione forzata con la frase "____".',array['tre generazioni di imbecilli sono abbastanza'],'La sentenza non è mai stata formalmente annullata.','Non verificato (da memoria)'),
('DRK-034','Dark/Politically incorrect','Fino al 1976 la Svezia sterilizzò per legge ____.',array['circa 60.000 persone'],'Erano considerate "inadatte" a fare figli.','Non verificato (da memoria)'),
('DRK-035','Dark/Politically incorrect','La sorella di JFK, a 23 anni, fu ____ per volere del padre.',array['operata al cervello'],'Rosemary Kennedy rimase invalida per tutta la vita.','Non verificato (da memoria)'),
('DRK-036','Dark/Politically incorrect','Le "Radium Girls" ____ pennelli intinti nel radio.',array['si mettevano in bocca'],'Dipingevano quadranti di orologi che brillavano al buio. Molte si ammalarono gravemente.','Non verificato (da memoria)'),
('DRK-037','Dark/Politically incorrect','Hugo Boss produceva ____ con ____.',array['le uniformi delle SS','il lavoro forzato'],'L''azienda si è scusata ufficialmente nel 2011.','Non verificato (da memoria)'),
('FOO-056','Food & Drink','La Fanta nacque ____.',array['nella Germania nazista'],'Con la guerra lo sciroppo della Coca-Cola non arrivava più, e la filiale tedesca inventò una bibita con quello che c''era.','Verificato'),
('DRK-038','Dark/Politically incorrect','Il padre delle armi chimiche vinse ____.',array['il Nobel per la Chimica'],'Fritz Haber lo vinse per aver inventato i fertilizzanti artificiali.','Non verificato (da memoria)'),
('HIS-024','History','Nella Prima guerra mondiale l''esercito italiano fucilava soldati ____.',array['estratti a sorte'],'Era la decimazione, usata per punire interi reparti.','Non verificato (da memoria)'),
('DRK-039','Dark/Politically incorrect','In guerra il Giappone costrinse decine di migliaia di donne a ____.',array['prostituirsi per i militari'],'Le chiamavano "donne di conforto". Venivano soprattutto dalla Corea.','Non verificato (da memoria)'),
('DRK-041','Dark/Politically incorrect','Durante il genocidio del Ruanda una radio ____.',array['leggeva in diretta i nomi delle persone da uccidere'],'La radio incitava all''odio e indicava dove trovare le vittime.','Non verificato (da memoria)'),
('DRK-042','Dark/Politically incorrect','Sotto i Khmer rossi potevi essere ucciso solo perché ____.',array['portavi gli occhiali'],'Gli occhiali erano visti come un segno di istruzione, e gli istruiti erano nemici del regime. Bastavano anche le mani morbide o parlare una lingua straniera.','Verificato'),
('DRK-043','Dark/Politically incorrect','Nella carestia ucraina degli anni ''30 più di 2.500 persone furono condannate per ____.',array['cannibalismo'],'È la grande carestia del 1932-33, sotto Stalin.','Non verificato (da memoria)'),
('HIS-025','History','Nel 1958 Mao ordinò lo sterminio ____.',array['dei passeri'],'Li accusava di mangiare il grano. Senza passeri gli insetti si moltiplicarono, e questo contribuì a una carestia.','Non verificato (da memoria)'),
('HIS-026','History','Secondo un cronista dell''epoca, nel 1346, durante un assedio, i mongoli catapultavano oltre le mura ____.',array['i cadaveri dei morti di peste'],'Successe a Caffa, in Crimea. Il racconto viene da un solo notaio italiano che però non era presente, e oggi molti storici ne dubitano. Se vero, sarebbe uno dei primi casi di guerra biologica.','Verificato'),
('DRK-044','Dark/Politically incorrect','A Jonestown più di 900 persone morirono bevendo ____.',array['una bibita al cianuro'],'Era il 1978, in Guyana. I seguaci di una setta furono spinti a bere dal loro capo.','Non verificato (da memoria)'),
('DRK-045','Dark/Politically incorrect','I 39 membri della setta Heaven''s Gate si ____ tutti con ____.',array['suicidarono','le stesse Nike ai piedi'],'Era il 1997. Credevano che un''astronave li avrebbe portati via.','Non verificato (da memoria)'),
('DRK-046','Dark/Politically incorrect','Nel 1814 a Londra otto persone annegarono in ____.',array['un''onda di birra'],'Un tino gigante di una birreria cedette e la birra allagò le case vicine.','Non verificato (da memoria)'),
('HIS-027','History','Nel 1962 in Tanzania scoppiò un''epidemia di ____.',array['risate incontrollabili'],'Partì da una scuola e andò avanti per mesi.','Non verificato (da memoria)'),
('GEO-007','Geography','Nel 1986 un lago in Camerun ____ che uccise 1.700 persone nel sonno.',array['rilasciò un gas'],'Era anidride carbonica accumulata sul fondo del lago Nyos, uscita tutta insieme.','Non verificato (da memoria)'),
('DRK-047','Dark/Politically incorrect','I sopravvissuti a uno schianto aereo sulle Ande resistettero 72 giorni ____.',array['mangiando i compagni morti'],'Era il 1972: a bordo c''era una squadra di rugby uruguaiana.','Non verificato (da memoria)'),
('HIS-028','History','Per decapitare Maria Stuarda servirono ____.',array['più colpi d''ascia'],'Era il 1587: il boia non riuscì al primo colpo.','Non verificato (da memoria)'),
('HIS-029','History','Fino al Novecento nel coro della Cappella Sistina cantavano ____.',array['i castrati'],'Venivano castrati da bambini per conservare la voce acuta.','Non verificato (da memoria)'),
('ANI-009','Animal kingdom','____ sott''acqua trattiene il respiro più a lungo di un delfino.',array['Il bradipo'],'Rallentando il battito del cuore può restare sott''acqua anche decine di minuti.','Non verificato (da memoria)'),
('ANI-010','Animal kingdom','Il collo della giraffa ha ____, come ____.',array['sette vertebre','quello umano'],'Sono solo molto più lunghe.','Non verificato (da memoria)'),
('ANI-011','Animal kingdom','Il polpo ha ____ e ____.',array['tre cuori','il sangue blu'],'Il sangue è blu perché trasporta l''ossigeno con il rame invece che con il ferro.','Non verificato (da memoria)'),
('ANI-012','Animal kingdom','I koala hanno ____ quasi uguali alle nostre.',array['impronte digitali'],'Sono così simili che potrebbero confondere un investigatore.','Non verificato (da memoria)'),
('ANI-013','Animal kingdom','Gli squali esistono da prima ____.',array['degli alberi'],'Gli squali esistono da circa 400 milioni di anni.','Non verificato (da memoria)'),
('ANI-014','Animal kingdom','I fenicotteri sono rosa perché mangiano ____.',array['gamberetti e alghe'],'Da piccoli sono grigi: il rosa arriva con i pigmenti del cibo.','Non verificato (da memoria)'),
('ANI-015','Animal kingdom','Quando muore ____ dei pesci pagliaccio, il maschio più grosso ____.',array['la femmina','cambia sesso'],'Nel gruppo comanda una sola femmina. Nemo, nella realtà, sarebbe andato diversamente.','Non verificato (da memoria)'),
('ANI-016','Animal kingdom','Una specie di medusa, quando invecchia, ____.',array['torna giovane e ricomincia da capo'],'È la Turritopsis, detta "medusa immortale": può ripetere il ciclo all''infinito.','Non verificato (da memoria)'),
('FOO-058','Food & Drink','Per la botanica la fragola non è ____, mentre ____ sì.',array['una bacca','la banana'],'Per i botanici sono bacche anche pomodori e melanzane.','Verificato'),
('FOO-059','Food & Drink','Fuori dal Giappone il wasabi dei ristoranti è quasi sempre ____.',array['una radice piccante colorata di verde'],'Il vero wasabi è difficile da coltivare e costa moltissimo.','Verificato'),
('FOO-060','Food & Drink','Mangiata in grandi quantità, la noce moscata ____.',array['provoca allucinazioni'],'Ne servono 2-3 cucchiai, e gli effetti sono soprattutto sgradevoli: nausea e tachicardia.','Verificato'),
('HIS-030','History','Cleopatra visse più vicina nel tempo ____ che alla costruzione della piramide di Giza.',array['allo sbarco sulla Luna'],'La piramide di Giza è così antica che per Cleopatra era già un monumento vecchio di millenni.','Non verificato (da memoria)'),
('HIS-031','History','L''Università di Oxford è più antica ____.',array['dell''Impero azteco'],'A Oxford si insegnava già secoli prima che nascesse l''impero azteco.','Non verificato (da memoria)'),
('HIS-032','History','Quando furono costruite le piramidi, su un''isola russa vivevano ancora ____.',array['i mammut'],'Gli ultimi mammut sopravvissero su un''isola dell''Artico fino a circa 4.000 anni fa.','Non verificato (da memoria)'),
('GEO-008','Geography','Il nome completo di Bangkok in thailandese ha ____.',array['più di 160 lettere'],'Il nome cerimoniale completo conta circa 168 caratteri ed è considerato il nome di città più lungo del mondo. I thailandesi la chiamano semplicemente Krung Thep.','Verificato'),
('GEO-009','Geography','Tecnicamente, ____ ha il più alto tasso di criminalità del mondo.',array['Il Vaticano'],'È un trucco statistico: pochissimi abitanti, milioni di turisti e molti borseggi e scippi.','Non verificato (da memoria)'),
('GEO-010','Geography','Il Canada ha ____ di tutto il resto del mondo messo insieme.',array['più laghi'],'Sono centinaia di migliaia.','Non verificato (da memoria)'),
('GEO-011','Geography','La Russia ha una superficie più grande di quella ____.',array['di Plutone'],'La Russia misura circa 17 milioni di km quadrati, poco più della superficie di Plutone.','Non verificato (da memoria)'),
('GEO-012','Geography','Il paese con più fusi orari al mondo: ____.',array['la Francia'],'Merito dei territori d''oltremare sparsi per il mondo.','Non verificato (da memoria)'),
('ANI-017','Animal kingdom','La più grande popolazione di cammelli selvatici del mondo vive ____.',array['in Australia'],'Furono portati nell''Ottocento come animali da trasporto e poi liberati.','Non verificato (da memoria)'),
('SCI-052','Science','Su Venere un giorno dura ____.',array['più di un anno'],'Venere ruota su sé stessa così lentamente che fa prima a completare un giro attorno al Sole.','Non verificato (da memoria)'),
('SCI-053','Science','Sulla Luna gli astronauti hanno lasciato ____.',array['96 sacchetti di pipì, cacca e vomito'],'Lasciati dalle missioni Apollo per alleggerire i moduli al ritorno.','Non verificato (da memoria)'),
('SCI-054','Science','Sulla Luna l''astronauta Charlie Duke lasciò ____.',array['una foto della sua famiglia'],'Missione Apollo 16, 1972. La foto è ancora lì.','Non verificato (da memoria)'),
('SCI-055','Science','Nello spazio gli astronauti diventano ____.',array['più alti di qualche centimetro'],'Senza gravità la colonna vertebrale si distende. Tornati a terra si riaccorciano.','Non verificato (da memoria)'),
('SCI-056','Science','Nel corpo umano c''è abbastanza ferro per fare ____.',array['un piccolo chiodo'],'Pochi grammi in tutto, quasi tutti nel sangue.','Non verificato (da memoria)'),
('SCI-057','Science','Lo stomaco rinnova di continuo il suo ____ per ____.',array['rivestimento','non digerire sé stesso'],'Lo fa ogni pochi giorni: l''acido è abbastanza forte da corrodere i tessuti.','Non verificato (da memoria)'),
('POP-004','Pop culture','Il primo video su YouTube mostra un ragazzo ____.',array['allo zoo che parla degli elefanti'],'Si intitola "Me at the zoo", è del 2005 e dura pochi secondi. Il ragazzo è uno dei fondatori del sito.','Verificato'),
('POP-005','Pop culture','La prima email di spam fu mandata nel 1978 per ____.',array['pubblicizzare dei computer'],'Arrivò a qualche centinaio di utenti della rete che ha preceduto internet.','Verificato'),
('POP-006','Pop culture','Nintendo, fondata nel 1889, ____.',array['produceva carte da gioco'],'Erano carte tradizionali giapponesi. I videogiochi arrivarono quasi un secolo dopo.','Verificato'),
('POP-007','Pop culture','Ogni anno la LEGO produce ____ di qualunque altra azienda.',array['più pneumatici'],'Sono le ruote minuscole dei suoi veicoli giocattolo: centinaia di milioni all''anno.','Verificato'),
('POP-008','Pop culture','Il nome IKEA unisce le iniziali del fondatore, della ____ e del ____.',array['sua fattoria','suo villaggio'],'Ingvar Kamprad, la fattoria Elmtaryd e il villaggio di Agunnaryd.','Verificato'),
('HIS-033','History','Un francese mangiò ____, a pezzi, in due anni.',array['un aereo intero'],'Si chiamava Michel Lotito ed era famoso per mangiare metallo e vetro.','Non verificato (da memoria)'),
('SCI-058','Science','Un ranger americano fu ____ e sopravvisse sempre.',array['colpito da sette fulmini'],'Si chiamava Roy Sullivan ed è nel Guinness dei primati.','Non verificato (da memoria)'),
('HIS-034','History','Un uomo giapponese sopravvisse ____ in tre giorni.',array['a due bombe atomiche'],'Si chiamava Tsutomu Yamaguchi: era a Hiroshima per lavoro e tornò a casa, a Nagasaki, in tempo per la seconda bomba. Nel 2009 fu il primo riconosciuto ufficialmente come sopravvissuto a entrambe.','Verificato'),
('HIS-035','History','Una donna ____, inclusi i naufragi del Titanic e del Britannic, la sua nave gemella.',array['sopravvisse a tre incidenti navali'],'Si chiamava Violet Jessop. Nel 1911 era cameriera sull''Olympic quando urtò una nave da guerra; nel 1912 era sul Titanic e si salvò su una scialuppa; nel 1916 era sul Britannic, nave ospedale, come volontaria della Croce Rossa, quando affondò per una mina.','Verificato'),
('HIS-036','History','Un soldato giapponese combatté nella giungla ____, convinto che la guerra non fosse finita.',array['fino al 1974'],'Hiroo Onoda si arrese solo quando il suo vecchio comandante andò di persona a dargli l''ordine.','Non verificato (da memoria)'),
('HIS-037','History','La guerra più breve della storia durò ____.',array['circa 38 minuti'],'Regno Unito contro Zanzibar, 1896.','Non verificato (da memoria)'),
('HIS-038','History','Nel 1859 USA e Regno Unito sfiorarono la guerra per colpa di ____.',array['un maiale'],'Un colono americano sparò al maiale di un inglese su un''isola contesa. L''unica vittima della crisi fu il maiale.','Non verificato (da memoria)'),
('HIS-039','History','Nel 1925 Grecia e Bulgaria fecero una breve guerra per ____.',array['un cane che aveva attraversato il confine'],'Secondo il racconto più diffuso, un soldato greco fu ucciso mentre lo rincorreva.','Non verificato (da memoria)'),
('POP-009','Pop culture','Il Monopoly nasce da un gioco ____ per criticare i grandi proprietari terrieri.',array['ideato da una donna'],'Si chiamava Elizabeth Magie e lo brevettò nel 1904: voleva mostrare quanto fosse ingiusto il monopolio.','Verificato'),
('HIS-040','History','Nella Seconda guerra mondiale le ____ mandate ai prigionieri nascondevano mappe e soldi veri.',array['scatole del Monopoly'],'Servivano ad aiutarli a fuggire.','Non verificato (da memoria)'),
('POP-010','Pop culture','Abramo Lincoln è nella Hall of Fame ____.',array['del wrestling'],'Da giovane era un lottatore famoso nella sua zona, e perse pochissimi incontri.','Verificato'),
('HIS-041','History','Secondo un testimone, al funerale di un presidente americano ____ fu portato via perché non smetteva di dire parolacce.',array['il suo pappagallo'],'Il presidente era Andrew Jackson, morto nel 1845, e il pappagallo si chiamava Poll. L''unico racconto è la lettera di un reverendo presente al funerale, scritta decenni dopo.','Verificato'),
('HIS-042','History','Einstein rifiutò di diventare ____.',array['presidente di Israele'],'Gli fu offerto nel 1952, dopo la morte del primo presidente. Rispose che per tutta la vita si era occupato di questioni oggettive e non aveva l''esperienza per trattare con le persone.','Verificato'),
('HIS-043','History','Theodore Roosevelt, colpito al petto da un proiettile, ____.',array['fece lo stesso un comizio di circa 90 minuti'],'Il proiettile fu rallentato dal discorso piegato che teneva in tasca.','Non verificato (da memoria)'),
('HIS-044','History','Durante la guerra la futura regina Elisabetta II faceva ____ e ____.',array['la meccanica','l''autista di camion'],'Si arruolò a 18 anni nel servizio ausiliario femminile.','Non verificato (da memoria)'),
('POP-011','Pop culture','Il dottor Seuss scrisse "Prosciutto e uova verdi" per vincere una scommessa: ____.',array['scrivere un libro con solo 50 parole diverse'],'La scommessa era con il suo editore. È diventato uno dei libri per bambini più venduti di sempre.','Verificato'),
('DRK-049','Dark/Politically incorrect','La CIA somministrò ____ a cittadini ignari.',array['LSD'],'Il progetto si chiamava MKUltra e cercava tecniche di controllo mentale.','Non verificato (da memoria)'),
('HIS-045','History','Nel 1962 i vertici militari USA proposero ____ per giustificare un attacco a Cuba.',array['finti attentati contro americani'],'Il piano si chiamava Operazione Northwoods: prevedeva anche attentati in città americane e aerei dirottati, da far ricadere su Cuba. Il governo Kennedy non lo approvò mai.','Verificato'),
('DRK-050','Dark/Politically incorrect','A fine Ottocento un serial killer di Chicago costruì ____.',array['un hotel con trappole e stanze senza finestre'],'H.H. Holmes, ai tempi dell''Expo del 1893. Molti dettagli del suo "castello" sono stati ingigantiti dai giornali.','Non verificato (da memoria)'),
('DRK-051','Dark/Politically incorrect','Nel centro di Città del Messico sono state trovate torri azteche fatte di ____.',array['centinaia di teschi umani'],'Gli Aztechi esponevano così i teschi delle vittime dei sacrifici.','Non verificato (da memoria)'),
('GEO-013','Geography','Le catacombe di Parigi contengono le ossa di ____.',array['circa 6 milioni di persone'],'Furono trasferite lì dai cimiteri della città, ormai troppo pieni.','Non verificato (da memoria)'),
('GEO-014','Geography','In una chiesa della Repubblica Ceca c''è un lampadario fatto ____.',array['interamente di ossa umane'],'È l''ossario di Sedlec, decorato con le ossa di decine di migliaia di persone.','Non verificato (da memoria)'),
('HIS-046','History','Dopo la guerra gli USA assunsero ____.',array['oltre mille scienziati nazisti'],'Era l''operazione Paperclip. Tra loro c''era il futuro costruttore dei razzi della NASA.','Non verificato (da memoria)'),
('HIS-047','History','A Chernobyl, quando i robot si ruppero, dei soldati ____.',array['spalarono a mano i detriti radioattivi dal tetto'],'Li chiamavano "bio-robot": potevano restare sul tetto solo per pochissimo tempo.','Non verificato (da memoria)'),
('SCI-059','Science','Un fisico teneva separate due semisfere di plutonio con ____: sbagliò e morì in nove giorni.',array['un cacciavite'],'Louis Slotin, 1946. Il cacciavite scivolò per un istante e lui ricevette una dose letale di radiazioni.','Non verificato (da memoria)'),
('DRK-052','Dark/Politically incorrect','Negli anni ''20 un''acqua al radio venduta come tonico faceva ____ a chi la beveva.',array['disintegrare la mascella'],'Si chiamava Radithor.','Non verificato (da memoria)'),
('DRK-053','Dark/Politically incorrect','Nell''Ottocento la carta da parati verde conteneva ____.',array['arsenico'],'Il colore verde più di moda era fatto con l''arsenico, e poteva intossicare chi viveva in quelle stanze.','Non verificato (da memoria)'),
('DRK-054','Dark/Politically incorrect','Nell''Ottocento si facevano foto ai ____, messi in posa come ____.',array['morti','se fossero vivi'],'Spesso era l''unica foto che la famiglia aveva di quella persona, bambini compresi.','Non verificato (da memoria)'),
('DRK-056','Dark/Politically incorrect','Negli anni ''50 un farmaco contro la nausea dato alle donne incinte fece ____.',array['nascere migliaia di bambini malformati'],'Era la talidomide.','Non verificato (da memoria)'),
('HIS-048','History','Negli anni ''40 una pubblicità di sigarette diceva che ____.',array['più medici fumavano Camel'],'Lo slogan diceva che i medici fumavano Camel più di ogni altra sigaretta.','Non verificato (da memoria)'),
('HIS-049','History','Nel 1898 la Bayer vendeva ____ come ____.',array['l''eroina','sciroppo per la tosse'],'All''inizio era presentata come un rimedio sicuro.','Non verificato (da memoria)'),
('HIS-050','History','Nell''Ottocento si vendevano gocce per il mal di denti dei bambini a base di ____.',array['cocaina'],'La cocaina era legale e si trovava in molti medicinali.','Non verificato (da memoria)'),
('DRK-057','Dark/Politically incorrect','Nel 1936 l''ultima esecuzione pubblica degli USA attirò ____.',array['circa 20.000 spettatori'],'Successe in Kentucky.','Non verificato (da memoria)'),
('DRK-058','Dark/Politically incorrect','A inizio Novecento la Germania sterminò due popoli della Namibia e mandò ____ in patria per ricerche "razziali".',array['i loro teschi'],'Erano gli Herero e i Nama, tra il 1904 e il 1908.','Non verificato (da memoria)'),
('DRK-060','Dark/Politically incorrect','In Australia fino agli anni ''70 lo Stato toglieva ____ alle famiglie.',array['i bambini aborigeni'],'Sono le "generazioni rubate": i bambini venivano cresciuti in istituti o da famiglie bianche.','Non verificato (da memoria)'),
('DRK-063','Dark/Politically incorrect','Un medico di famiglia inglese uccise oltre 200 pazienti, e fu scoperto solo perché ____.',array['falsificò un testamento a suo favore'],'Harold Shipman uccideva con overdose di diamorfina, cioè eroina medica. Fu arrestato nel 1998, dopo che la figlia di una paziente si accorse che il testamento della madre, tutto a favore del medico, era falso.','Verificato'),
('DRK-064','Dark/Politically incorrect','Nel 1995 una setta liberò ____ nella metropolitana di Tokyo.',array['un gas velenoso'],'La setta si chiamava Aum Shinrikyo.','Non verificato (da memoria)'),
('DRK-066','Dark/Politically incorrect','Il kuru è una malattia che colpiva chi mangiava ____.',array['il cervello dei morti'],'Era un rito funebre di un popolo della Papua Nuova Guinea.','Non verificato (da memoria)'),
('DRK-067','Dark/Politically incorrect','In Cina fino al 1905 esisteva la tortura della "____". Il condannato veniva ucciso ____.',array['morte dei mille tagli','lentamente, un taglio alla volta'],'Il condannato veniva ucciso lentamente, un taglio alla volta.','Non verificato (da memoria)'),
('DRK-068','Dark/Politically incorrect','Nel 1531 Enrico VIII rese legale ____.',array['bollire vivi chi avvelenava le persone'],'La legge nacque dopo che un cuoco avvelenò la zuppa di un vescovo.','Non verificato (da memoria)'),
('HIS-051','History','Alle Olimpiadi del 1900 una delle gare era ____.',array['il tiro a segno su piccioni veri'],'Fu l''unica volta nella storia delle Olimpiadi in cui si uccisero animali di proposito.','Non verificato (da memoria)'),
('GEO-015','Geography','Sull''Everest ____ sono usati come punti di riferimento dagli scalatori.',array['alcuni cadaveri'],'Recuperare i corpi a quelle altitudini è difficilissimo, quindi molti restano dove sono.','Non verificato (da memoria)'),
('DRK-070','Dark/Politically incorrect','Secondo la tradizione Ivan il Terribile uccise a colpi di bastone ____.',array['il figlio ed erede'],'Successe nel 1581, durante una lite. Le fonti dell''epoca parlano di un colpo del bastone del padre, ma mancano prove definitive. Un famoso quadro di Repin lo ritrae disperato con il figlio tra le braccia.','Verificato'),
('DRK-071','Dark/Politically incorrect','Il pittore Caravaggio ____ e fu condannato a morte.',array['uccise un uomo in una rissa'],'Passò gli ultimi anni in fuga tra Napoli, Malta e la Sicilia.','Non verificato (da memoria)'),
('DRK-072','Dark/Politically incorrect','____ fu rubato da due "studiosi del cranio" pochi giorni dopo la sepoltura.',array['Il teschio di Haydn'],'Morì a Vienna nel 1809. Due appassionati di frenologia pagarono un becchino per avere la testa: volevano trovarci il «bernoccolo della musica». Il cranio fu riunito al corpo solo nel 1954.','Verificato'),
('SCI-060','Science','Chi ha la sindrome della mano aliena ha ____.',array['una mano che si muove contro la sua volontà'],'Può comparire dopo lesioni al cervello: la mano afferra oggetti o tocca cose da sola.','Non verificato (da memoria)'),
('SCI-061','Science','Chi ha la sindrome di Cotard è convinto ____.',array['di essere morto'],'È una rara sindrome psichiatrica: alcuni pazienti smettono di mangiare perché si credono già morti.','Non verificato (da memoria)'),
('SCI-063','Science','Il corpo umano emette ____.',array['una luce debolissima'],'È troppo debole per essere vista a occhio nudo: la rilevano solo fotocamere sensibilissime.','Non verificato (da memoria)'),
('SCI-064','Science','Nasciamo con ____, ma da adulti ne abbiamo 206.',array['circa 300 ossa'],'Crescendo molte si fondono tra loro, per esempio quelle del cranio.','Non verificato (da memoria)'),
('SCI-065','Science','____ ha un''impronta unica, come le dita.',array['La lingua umana'],'Forma e superficie sono diverse da persona a persona.','Non verificato (da memoria)'),
('GEO-016','Geography','In Corea del Sud fino al 2023 si nasceva già ____.',array['con un anno di età'],'Con il sistema tradizionale si aveva un anno alla nascita e se ne aggiungeva uno a ogni Capodanno.','Non verificato (da memoria)'),
('ANI-018','Animal kingdom','L''axolotl rigenera ____.',array['arti, cuore e parti del cervello'],'È una salamandra messicana che resta "cucciola" per tutta la vita.','Non verificato (da memoria)'),
('ANI-019','Animal kingdom','I tardigradi sopravvivono ____.',array['nel vuoto dello spazio'],'Sono animaletti grandi meno di un millimetro, quasi indistruttibili.','Non verificato (da memoria)'),
('ANI-020','Animal kingdom','I ratti ____ quando vengono ____.',array['ridono','solleticati'],'Emettono ultrasuoni che noi non sentiamo.','Non verificato (da memoria)'),
('ANI-022','Animal kingdom','Gli ippopotami producono ____ che li protegge ____.',array['un liquido rossastro','dal sole'],'Funziona da crema solare e da disinfettante. Un tempo si credeva che sudassero sangue.','Non verificato (da memoria)'),
('ANI-023','Animal kingdom','L''animale che uccide più persone al mondo è ____.',array['la zanzara'],'Circa 700.000 morti all''anno, per le malattie che trasmette, come la malaria.','Non verificato (da memoria)'),
('FOO-062','Food & Drink','Gli anacardi crudi contengono la stessa tossina ____.',array['dell''edera velenosa'],'Si chiama urushiolo. Quelli in commercio sono trattati con il calore per eliminarla.','Verificato'),
('ANI-024','Animal kingdom','Dopo la morte di Pablo Escobar ____ si sono moltiplicati e ora sono oltre cento.',array['i suoi ippopotami'],'Ne aveva quattro nel suo zoo privato: oggi sono oltre cento.','Non verificato (da memoria)'),
('ANI-025','Animal kingdom','Una specie di gambero può colpire così forte da ____.',array['rompere il vetro degli acquari'],'È la canocchia pavone (mantis shrimp): il suo colpo è tra i più veloci del regno animale.','Non verificato (da memoria)'),
('GEO-017','Geography','In Giappone ci sono più ____ che bambini.',array['animali domestici'],'Cani e gatti hanno superato da anni il numero dei bambini.','Non verificato (da memoria)'),
('GEO-018','Geography','In Turkmenistan ____ dal 1971.',array['un cratere di gas brucia'],'Lo chiamano "porta dell''inferno".','Non verificato (da memoria)'),
('GEO-019','Geography','In Finlandia ci sono ____ per 5,5 milioni di abitanti.',array['circa 3 milioni di saune'],'Più o meno una ogni due persone.','Non verificato (da memoria)'),
('GEO-020','Geography','L''Italia ha più ____ di qualsiasi altro paese.',array['siti UNESCO'],'Sono una sessantina.','Non verificato (da memoria)'),
('GEO-021','Geography','Nella Fontana di Trevi ogni anno si raccolgono ____.',array['oltre un milione di euro di monete'],'Nel 2022 sono stati raccolti circa 1,4 milioni di euro. Le monete vanno alla Caritas di Roma, che le usa per aiutare chi è in difficoltà.','Verificato'),
('GEO-022','Geography','Venezia poggia su ____.',array['milioni di pali di legno'],'Sott''acqua, senza ossigeno, il legno non marcisce.','Non verificato (da memoria)'),
('GEO-023','Geography','In Australia c''è ____ lunga oltre 3.000 km.',array['una recinzione anti-conigli'],'Fu costruita a inizio Novecento per fermare l''invasione dei conigli. Non bastò.','Non verificato (da memoria)'),
('GEO-024','Geography','Il lago Baikal contiene ____ dell''acqua dolce superficiale del mondo.',array['circa il 20%'],'È il lago più profondo del mondo.','Non verificato (da memoria)'),
('GEO-025','Geography','Il Mar Morto si trova a ____ sotto il livello del mare.',array['circa 430 metri'],'È il punto più basso delle terre emerse.','Non verificato (da memoria)'),
('GEO-027','Geography','Seimila anni fa il Sahara era ____.',array['verde, con laghi e savana'],'Lo provano le pitture rupestri con animali della savana.','Non verificato (da memoria)'),
('GEO-028','Geography','In Islanda quasi nessuno ha ____.',array['un cognome di famiglia'],'Il "cognome" dice solo di chi sei figlio: Jónsson, figlio di Jón; Jónsdóttir, figlia di Jón.','Non verificato (da memoria)'),
('GEO-029','Geography','Sul Rio delle Amazzoni non c''è ____.',array['nemmeno un ponte'],'Il fiume è larghissimo e attraversa zone quasi senza strade: si usano i traghetti.','Non verificato (da memoria)'),
('GEO-030','Geography','Invece del PIL, il Bhutan misura la "____".',array['felicità interna lorda'],'Tiene conto di cose come benessere, cultura e ambiente.','Non verificato (da memoria)'),
('GEO-031','Geography','In giapponese esiste una parola, karoshi, per ____.',array['la morte da troppo lavoro'],'È un fenomeno riconosciuto ufficialmente.','Non verificato (da memoria)'),
('GEO-032','Geography','Un cucchiaino di stella di neutroni pesa ____.',array['circa un miliardo di tonnellate'],'Le stelle di neutroni sono tra gli oggetti più densi dell''universo.','Non verificato (da memoria)'),
('SCI-066','Science','Nello spazio due pezzi di metallo a contatto ____.',array['si saldano da soli'],'Si chiama saldatura a freddo: nel vuoto manca lo strato di ossido che sulla Terra tiene separati i metalli.','Non verificato (da memoria)'),
('SCI-067','Science','Il Sole contiene ____ della massa del sistema solare.',array['il 99,86%'],'Tutti i pianeti, le lune e gli asteroidi messi insieme fanno il restante 0,14%.','Non verificato (da memoria)'),
('SCI-070','Science','Nel 1968 una sonda sovietica portò ____ attorno alla Luna, e tornarono vive.',array['due tartarughe'],'La sonda era la Zond 5.','Non verificato (da memoria)'),
('SCI-071','Science','Il primo "bug" informatico fu ____ trovata in un computer nel 1947.',array['una falena vera'],'Era finita dentro un computer nel 1947 e fu attaccata con lo scotch al registro dei guasti.','Non verificato (da memoria)'),
('POP-012','Pop culture','Il primo mouse era ____.',array['di legno'],'Lo costruì Douglas Engelbart negli anni ''60: un blocchetto di legno con due rotelle.','Verificato'),
('POP-013','Pop culture','Il primo SMS, nel 1992, diceva "____".',array['Merry Christmas'],'Lo mandò un ingegnere da un computer, perché i telefoni non avevano ancora la tastiera per scriverli.','Verificato'),
('POP-014','Pop culture','Nokia nacque nel 1865 come ____.',array['produttore di carta'],'Era una cartiera finlandese. Prima dei telefoni produsse anche stivali di gomma.','Verificato'),
('POP-015','Pop culture','Samsung, nata nel 1938, vendeva ____ e ____.',array['pesce secco','generi alimentari'],'Era una piccola ditta di commercio coreana. L''elettronica arrivò solo alla fine degli anni ''60.','Verificato'),
('POP-016','Pop culture','Il nome dell''azienda ____ viene da un personaggio del romanzo Moby Dick.',array['Starbucks'],'Starbuck è il primo ufficiale della nave del capitano Achab.','Verificato, da ricontrollare'),
('FOO-064','Food & Drink','In Sardegna esiste un formaggio, il casu marzu, con dentro ____.',array['larve vive'],'Le larve devono muoversi: se sono morte il formaggio è andato a male. La vendita è vietata.','Verificato'),
('FOO-065','Food & Drink','In Giappone per cucinare il pesce palla ____.',array['serve una licenza'],'Il fugu contiene un veleno mortale: i cuochi studiano anni per imparare a togliere le parti pericolose.','Verificato'),
('FOO-066','Food & Drink','Il "miele pazzo" della Turchia è ____, per via dei rododendri.',array['allucinogeno'],'Il nettare dei rododendri contiene una tossina. In dosi alte è pericoloso.','Verificato'),
('FOO-067','Food & Drink','Un tempo ____ si potevano noleggiare per una sera.',array['gli ananas'],'Erano rarissimi e costosissimi: si sfoggiavano alle feste come simbolo di ricchezza.','Da ricontrollare (dubbio noto)'),
('FOO-068','Food & Drink','Un hamburger di McDonald''s comprato in Islanda era ____.',array['ancora intatto dopo oltre dieci anni'],'Fu comprato nel 2009, l''ultimo giorno prima che McDonald''s lasciasse il paese.','Verificato'),
('FOO-069','Food & Drink','Nel 1807 Napoleone fu attaccato da ____.',array['una folla di conigli'],'Erano conigli d''allevamento liberati per una battuta di caccia: invece di scappare gli corsero incontro. L''aneddoto viene da una sola fonte.','Verificato, da ricontrollare'),
('HIS-053','History','Nikola Tesla si innamorò di ____.',array['un piccione'],'Raccontò di amarla come un uomo ama una donna.','Non verificato (da memoria)'),
('HIS-054','History','Isaac Newton ____ per studiare la vista.',array['si infilò un ago nell''occhio'],'Voleva capire come la pressione sull''occhio cambiasse i colori che vedeva.','Non verificato (da memoria)'),
('HIS-055','History','Al Museo Galileo di Firenze è esposto ____.',array['il dito medio di Galileo'],'Fu staccato dal corpo quasi un secolo dopo la sua morte.','Non verificato (da memoria)'),
('HIS-056','History','Michelangelo ebbe ____.',array['il naso rotto da un pugno di un collega'],'Era un altro scultore, Pietro Torrigiano. Il naso gli rimase storto per sempre.','Non verificato (da memoria)'),
('HIS-057','History','Nei capelli di Beethoven furono trovate ____.',array['alte dosi di piombo'],'Per anni si è pensato che il piombo spiegasse le sue malattie, ma la questione è ancora discussa.','Non verificato (da memoria)'),
('HIS-058','History','La Gioconda fu rubata nel 1911 da un italiano che ____.',array['voleva riportarla in Italia'],'Si chiamava Vincenzo Peruggia. Il quadro restò nascosto per oltre due anni.','Non verificato (da memoria)'),
('HIS-059','History','Nel 1926 Agatha Christie ____.',array['sparì per 11 giorni'],'Fu ritrovata in un albergo, registrata sotto un altro nome. Non spiegò mai cosa fosse successo.','Non verificato (da memoria)'),
('HIS-061','History','I vichinghi non portavano ____.',array['elmi con le corna'],'È un''invenzione dell''Ottocento, resa popolare dal teatro e dalle illustrazioni.','Non verificato (da memoria)'),
('POP-017','Pop culture','A Wimbledon 2010 Isner e Mahut giocarono una partita di ____.',array['11 ore e 5 minuti'],'Durò tre giorni. L''ultimo set finì 70 a 68.','Verificato'),
('POP-018','Pop culture','Il ____ fu sport olimpico fino al 1920.',array['tiro alla fune'],'Fu disciplina olimpica dal 1900 al 1920.','Verificato'),
('POP-019','Pop culture','Nel 2002 in Madagascar una partita finì 149-0, tutti ____.',array['autogol'],'La squadra segnò apposta nella propria porta per protestare contro l''arbitro.','Verificato'),
('POP-020','Pop culture','Nel 1939 un match di cricket finì in pareggio dopo ____.',array['oltre 10 giorni'],'Doveva essere una partita senza limiti di tempo, ma gli inglesi dovevano prendere la nave per tornare a casa.','Verificato'),
('HIS-063','History','Nel 1950 la Marina USA ____ senza avvisare nessuno.',array['spruzzò batteri su San Francisco'],'Era un test per simulare un attacco biologico. Un uomo ne morì.','Non verificato (da memoria)'),
('HIS-064','History','Nel 1666 un uomo fu impiccato per aver appiccato il Grande incendio di Londra, ma ____.',array['non era in città'],'Robert Hubert confessò, ma era arrivato a Londra dopo l''inizio dell''incendio.','Non verificato (da memoria)'),
('HIS-065','History','Il medico Semmelweis, per aver chiesto ai colleghi di ____, finì in manicomio.',array['lavarsi le mani'],'Aveva capito che così si salvavano le partorienti, ma non fu creduto. In manicomio morì.','Non verificato (da memoria)'),
('HIS-066','History','Per provare il primo vaccino, Edward Jenner lo iniettò ____.',array['al figlio di otto anni del suo giardiniere'],'Era il vaccino contro il vaiolo.','Non verificato (da memoria)'),
('HIS-067','History','Negli anni ''50 a Las Vegas si elesse una "____".',array['Miss Bomba Atomica'],'I test nucleari nel deserto erano un''attrazione: i turisti li guardavano dagli alberghi.','Non verificato (da memoria)'),
('HIS-068','History','La guerra dei Cent''anni durò in realtà ____.',array['116 anni'],'Dal 1337 al 1453, con lunghe pause.','Non verificato (da memoria)'),
('HIS-069','History','Nel 1969 El Salvador e Honduras fecero una guerra dopo ____.',array['le partite di qualificazione ai Mondiali'],'È la "guerra del calcio": durò circa 100 ore. Le partite furono la scintilla di tensioni più profonde.','Non verificato (da memoria)'),
('HIS-070','History','Nel 1971 gli USA e la Cina ripresero i rapporti grazie a ____.',array['una squadra di ping-pong'],'È la "diplomazia del ping-pong": la squadra americana fu invitata in Cina.','Non verificato (da memoria)'),
('HIS-071','History','Papa Giovanni Paolo I regnò soltanto ____.',array['33 giorni'],'Morì nel 1978, poco più di un mese dopo l''elezione.','Non verificato (da memoria)'),
('SCI-072','Science','Gli appunti di Marie Curie sono ____.',array['ancora radioattivi'],'Si conservano in scatole di piombo.','Non verificato (da memoria)'),
('HIS-074','History','La testa di Oliver Cromwell restò ____ per circa 25 anni.',array['su un palo'],'Fu riesumato e decapitato da morto. Poi la testa passò tra i collezionisti fino al 1960.','Non verificato (da memoria)'),
('HIS-075','History','Il cuore di Chopin è conservato ____.',array['in un vaso di cognac'],'È murato in un pilastro della chiesa di Santa Croce a Varsavia. Chopin morì a Parigi nel 1849 e chiese che il cuore tornasse in Polonia: lo portò la sorella. Il liquido è con ogni probabilità cognac.','Verificato'),
('HIS-076','History','Il corpo di Lenin è imbalsamato da cent''anni, e un laboratorio dedicato lo ____.',array['ritocca periodicamente'],'È esposto a Mosca dal 1924.','Non verificato (da memoria)'),
('HIS-077','History','Il corpo di Evita Perón fu nascosto per anni ____.',array['in un cimitero di Milano sotto un nome falso'],'Rimase 14 anni al Cimitero Maggiore come «Maria Maggi de Magistris». I militari che avevano rovesciato Perón temevano che i peronisti usassero la salma come simbolo.','Verificato'),
('HIS-078','History','Nel 1978 ____ fu rubato per chiedere un riscatto.',array['il corpo di Charlie Chaplin'],'I due ladri furono presi e la bara fu ritrovata.','Non verificato (da memoria)'),
('HIS-079','History','Il re francese Carlo VI era convinto ____ e di potersi rompere.',array['di essere di vetro'],'Per paura di rompersi evitava che lo toccassero.','Non verificato (da memoria)'),
('HIS-080','History','Giovanna la Pazza si portò dietro ____ per molti mesi.',array['il cadavere del marito'],'Era Giovanna di Castiglia, regina dal 1504. Il marito Filippo il Bello morì a Burgos nel 1506 e lei volle portarne la bara fino a Granada: il viaggio durò più di otto mesi. Si racconta che aprisse la bara per guardarlo.','Verificato'),
('HIS-081','History','Un papa nominò cardinale il figlio di una mendicante che ____.',array['si occupava della sua scimmia'],'Il papa era Giulio III, nel 1550. Il ragazzo, Innocenzo, era figlio di una mendicante e aveva circa 18 anni; a Roma lo chiamavano «il cardinale scimmia». Fu uno scandalo.','Verificato'),
('HIS-082','History','Il "vomitorium" dell''antica Roma era ____.',array['un''uscita dello stadio'],'Non era una stanza per vomitare e continuare a mangiare: è un equivoco moderno.','Non verificato (da memoria)'),
('DRK-073','Dark/Politically incorrect','Il banchiere Roberto Calvi fu trovato impiccato sotto un ponte a Londra ____.',array['con dei mattoni in tasca'],'Era il 1982. Lo chiamavano "il banchiere di Dio" per i legami con il Vaticano.','Non verificato (da memoria)'),
('SCI-073','Science','In un famoso esperimento, due persone su tre diedero ____ a uno sconosciuto, solo perché glielo avevano ordinato.',array['una scossa che credevano mortale'],'Esperimento di Milgram: le scosse erano finte, ma i partecipanti non lo sapevano.','Non verificato (da memoria)'),
('SCI-074','Science','In un famoso esperimento gli psicologi insegnarono a un bambino ad aver paura ____.',array['dei topi bianchi'],'È l''esperimento del "piccolo Albert": oggi sarebbe considerato del tutto inaccettabile.','Non verificato (da memoria)'),
('SCI-075','Science','Per studiare l''affetto, uno psicologo toglieva i cuccioli di scimmia alle madri e dava loro ____.',array['madri finte di stoffa o filo'],'Harry Harlow voleva capire se ai piccoli serve più il cibo o il contatto.','Non verificato (da memoria)'),
('DRK-075','Dark/Politically incorrect','La CIA gestiva bordelli per ____ e osservarli.',array['drogare i clienti con LSD'],'Operazione "Midnight Climax", a San Francisco.','Non verificato (da memoria)'),
('DRK-077','Dark/Politically incorrect','Il serial killer più prolifico della storia USA ha confessato ____.',array['93 omicidi'],'Si chiamava Samuel Little.','Non verificato (da memoria)'),
('DRK-078','Dark/Politically incorrect','L''identità di Unabomber fu scoperta perché ____.',array['il fratello riconobbe lo stile del suo manifesto'],'Il manifesto era stato pubblicato sui giornali proprio nella speranza che qualcuno lo riconoscesse.','Non verificato (da memoria)'),
('DRK-079','Dark/Politically incorrect','Nel 1910 un assassino in fuga su una nave fu il primo criminale catturato grazie ____.',array['a un messaggio via radio'],'Era il dottor Crippen: il capitano lo riconobbe e avvisò la polizia via radio.','Non verificato (da memoria)'),
('DRK-080','Dark/Politically incorrect','Un serial killer americano fu identificato nel 2018 grazie a ____.',array['un sito che ricostruisce le famiglie dal DNA'],'È il Golden State Killer: gli investigatori trovarono dei suoi parenti tramite il DNA.','Non verificato (da memoria)'),
('DRK-081','Dark/Politically incorrect','Al Capone fu condannato per ____.',array['evasione fiscale'],'Non riuscirono mai a incastrarlo per i suoi crimini più gravi.','Non verificato (da memoria)'),
('DRK-082','Dark/Politically incorrect','Nel 2015 El Chapo evase da un carcere di massima sicurezza attraverso ____.',array['un tunnel lungo circa 1,5 km'],'Il tunnel sbucava nella doccia della sua cella.','Non verificato (da memoria)'),
('DRK-083','Dark/Politically incorrect','Per consegnarsi alle autorità, Pablo Escobar si fece costruire ____ con tanto di ____.',array['una prigione di lusso','campo da calcio'],'La chiamavano "La Catedral".','Non verificato (da memoria)'),
('DRK-084','Dark/Politically incorrect','Il pirata Barbanera si intrecciava ____ nella barba prima delle battaglie.',array['micce accese'],'Il fumo attorno alla faccia serviva a terrorizzare i nemici.','Non verificato (da memoria)'),
('HIS-085','History','Alfred Nobel lesse ____, uscito per errore.',array['il proprio annuncio di morte sul giornale'],'Lo chiamava "mercante di morte" per la dinamite. Si dice che per questo creò i premi Nobel.','Non verificato (da memoria)'),
('ANI-026','Animal kingdom','Il parassita "Toxoplasma" fa perdere ai topi ____.',array['la paura dei gatti'],'È il Toxoplasma: i topi sono perfino attirati dall''odore del gatto, così il parassita arriva dove vuole riprodursi.','Non verificato (da memoria)'),
('ANI-027','Animal kingdom','Un fungo trasforma le formiche in ____ che lo portano nel posto ideale per riprodursi.',array['zombie'],'È l''Ophiocordyceps: le porta a morire in alto su una foglia, da dove diffonde le spore.','Non verificato (da memoria)'),
('ANI-028','Animal kingdom','Una vespa trasforma gli scarafaggi in ____.',array['zombie'],'La vespa gioiello lo punge nel cervello e lo porta nella tana, dove le sue larve lo mangiano vivo.','Non verificato (da memoria)'),
('ANI-029','Animal kingdom','La rana Pipa fa uscire i suoi piccoli ____.',array['dalla pelle della schiena'],'È la rana Pipa: le uova crescono dentro la pelle della madre.','Non verificato (da memoria)'),
('ANI-030','Animal kingdom','In alcuni pesci degli abissi il maschio ____ con la femmina.',array['si fonde'],'Nei pesci pescatore il maschio, molto più piccolo, vive attaccato a lei come un parassita.','Non verificato (da memoria)'),
('ANI-031','Animal kingdom','Le lumache hanno ____ sulla lingua.',array['migliaia di denti'],'In alcune specie sono oltre 14.000.','Non verificato (da memoria)'),
('ANI-032','Animal kingdom','Le api giapponesi uccidono i calabroni ____.',array['facendoli morire di caldo'],'Li circondano in massa e fanno vibrare i muscoli finché la temperatura diventa letale.','Non verificato (da memoria)'),
('ANI-033','Animal kingdom','Il cavallo non può ____.',array['vomitare'],'Ha una valvola all''ingresso dello stomaco che lo impedisce.','Non verificato (da memoria)'),
